<?php

declare(strict_types=1);

/**
 * Batch638 REE foundation, legacy quantitative normalization, wave writer and
 * deterministic audit.  Run from the isolated Batch638 worktree.
 *
 * Modes: --foundation, --normalize-legacy, --run-wave=1..4, --audit, --write.
 * Every JSON write is atomic.  Wave creation is idempotent: an existing
 * validated Batch638 ID is reconciled, never regenerated.
 */

$root = dirname(__DIR__);
$expectedHead = '15086757c2af1a454ef08e341ab0c30f206836ac';
$today = '2026-10-01';
$args = array_slice($argv, 1);
$mode = 'audit';
foreach ($args as $arg) {
    if ($arg === '--foundation') $mode = 'foundation';
    elseif ($arg === '--normalize-legacy') $mode = 'normalize';
    elseif ($arg === '--refresh-foundation') $mode = 'foundation-refresh';
    elseif (preg_match('/^--run-wave=([1-4])$/', $arg, $m)) $mode = 'wave' . $m[1];
    elseif ($arg === '--repair-wave1') $mode = 'repair-wave1';
    elseif (preg_match('/^--validate-wave=([1-4])$/', $arg, $m)) $mode = 'validate-wave' . $m[1];
    elseif ($arg === '--normalize-diversity') $mode = 'normalize-diversity';
    elseif ($arg === '--finalize') $mode = 'finalize';
    elseif ($arg === '--write') $mode = 'audit-write';
    elseif ($arg === '--audit') $mode = 'audit';
}

const B638_BOARD = 'registered-electrical-engineering';
const B638_BATCH = 'batch638-ree-source-first';

function b638_read(string $root, string $path): array
{
    $full = $root . '/' . $path;
    if (!is_file($full)) throw new RuntimeException('Missing ' . $path);
    $data = json_decode((string) file_get_contents($full), true, 512, JSON_THROW_ON_ERROR);
    if (!is_array($data)) throw new RuntimeException('Invalid JSON container: ' . $path);
    return $data;
}

function b638_write(string $path, array $data): void
{
    $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION | JSON_THROW_ON_ERROR) . PHP_EOL;
    $tmp = $path . '.batch638.tmp';
    if (file_put_contents($tmp, $json, LOCK_EX) === false || !rename($tmp, $path)) {
        if (is_file($tmp)) unlink($tmp);
        throw new RuntimeException('Atomic write failed: ' . $path);
    }
}

function b638_hash(mixed $data): string
{
    if (is_array($data) && array_key_exists('audit_hash', $data)) unset($data['audit_hash']);
    return hash('sha256', json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR));
}

function b638_first(array $data): array
{
    return array_is_list($data) ? (is_array($data[0] ?? null) ? $data[0] : []) : $data;
}

function b638_assert_lineage(string $root, string $expected): array
{
    $head = trim((string) shell_exec('git -C ' . escapeshellarg($root) . ' rev-parse HEAD'));
    if ($head !== $expected) throw new RuntimeException('Expected Batch637 parent ' . $expected . '; found ' . $head);
    foreach (['2d29a990619e0fcfdfc58b7658b932b3827d9eb5','fd6adb49bc140ac148a90c705c33bf7901193487','25b7d30cf60310487e30e515266faf99935bb3bd','e640eed4d3e4c36c1264e0a60333ca103f5f1f7b'] as $ancestor) {
        $ok = trim((string) shell_exec('git -C ' . escapeshellarg($root) . ' merge-base --is-ancestor ' . escapeshellarg($ancestor) . ' HEAD; echo $?'));
        if ($ok !== '0') throw new RuntimeException('Missing required ancestor ' . $ancestor);
    }
    return ['expected_head'=>$expected,'head_before'=>$head,'ancestry'=>'PASS'];
}

function b638_source(string $id, string $title, string $role, string $authority, string $url, string $version, string $notes, string $today): array
{
    return ['id'=>$id,'title'=>$title,'source_type'=>$role,'authority'=>$authority,'url'=>$url,
        'publication_date'=>null,'retrieved_at'=>$today,'version'=>$version,'status'=>'verified_reference',
        'confidence'=>'authoritative_reference','source_role'=>$role,'volatility'=>'CURRENTNESS_TRACKED','notes'=>$notes];
}

