function b638_add_foundation_sources(array &$sources, string $today): array
{
    $index = [];
    foreach ($sources as $i => $s) $index[(string)($s['id'] ?? '')] = $i;
    $added = [];
    foreach (b638_sources_to_add($today) as $s) {
        if (!isset($index[$s['id']])) { $index[$s['id']] = count($sources); $sources[] = $s; $added[] = $s['id']; }
    }
    return $added;
}

function b638_legacy_semantics(array $q): array
{
    $id = (int)($q['id'] ?? 0);
    $text = strtolower(($q['question'] ?? '') . ' ' . ($q['explanation'] ?? ''));
    $numericContext = ($q['numeric'] ?? false) === true || in_array($id, [1580,1595,1634,1639,1651,1679,1680,1686], true);
    if (!$numericContext) return ['numeric_context'=>false,'class'=>'NON_NUMERICAL','calculation_required'=>false,'family'=>null];

    $conceptual = in_array($id, [1585,1595,1634,1639,1679,1680], true);
    $mixed = in_array($id, [], true);
    $class = $mixed ? 'MIXED_INTERPRETIVE' : ($conceptual ? 'CONCEPTUAL_QUANTITATIVE' : 'CALCULATION_REQUIRED');
    $leaf = (string)($q['taxonomy']['subcompetency_id'] ?? $q['taxonomy']['concept_id'] ?? 'ree-unmapped');
    $family = (string)($q['__family'] ?? '');
    if ($family === '') {
        $rules = [
            '/matrix|determinant|linear system|equation|slope|interpolation/' => 'algebraic-model-solution',
            '/phasor|complex|rectangular|quadrant|angle|impedance/' => 'complex-phasor-operation',
            '/derivative|minimum|velocity|integral|charge|calculus/' => 'calculus-rate-or-integral',
            '/probab|mean|normal|z-score|binomial|distribution|risk/' => 'probability-statistical-inference',
            '/series|sequence|sum of|geometric/' => 'sequence-series-sum',
            '/fourier|laplace|pole|time constant|transient/' => 'transform-response-model',
            '/discount|present worth|break-even|cost|economic/' => 'engineering-economics-decision',
            '/force|moment|stress|strain|beam|torque|acceleration/' => 'mechanics-equilibrium-material',
            '/heat|temperature|thermal|conduction|gas|pressure|buoyant/' => 'thermal-fluid-balance',
            '/diode|transistor|amplifier|filter|gain|adc|converter|emf|magnetic/' => 'electronics-device-or-signal',
            '/instrument|sensor|uncertainty|sample|oscilloscope|logger/' => 'measurement-and-instrumentation',
            '/breaker|fault|relay|ground|safety|hazard|energized/' => 'protection-safety-judgment',
            '/transformer|motor|slip|generator|machine|speed/' => 'machine-energy-conversion',
            '/feeder|line|demand|diversity|load factor|harmonic|transmission|distribution/' => 'power-system-operating-analysis',
            '/buck|boost|switching|duty ratio/' => 'power-electronic-conversion',
            '/control|feedback|nyquist/' => 'control-system-dynamics',
        ];
        foreach ($rules as $pattern => $candidate) if (preg_match($pattern, $text)) { $family = $candidate; break; }
        if ($family === '') $family = 'leaf-specific-quantitative-reasoning';
    }
    return ['numeric_context'=>true,'class'=>$class,'calculation_required'=>$class === 'CALCULATION_REQUIRED' || $class === 'MIXED_INTERPRETIVE','family'=>'legacy:' . $leaf . ':' . $family,'family_leaf'=>$leaf];
}

function b638_normalize_legacy(array &$questions): array
{
    $reviewed = 0;
    $classes = ['NON_NUMERICAL'=>0,'CONCEPTUAL_QUANTITATIVE'=>0,'CALCULATION_REQUIRED'=>0,'MIXED_INTERPRETIVE'=>0];
    $families = [];
    $legacy = $tagged = $recomputed = 0;
    foreach ($questions as &$q) {
        if (($q['board'] ?? '') !== B638_BOARD) continue;
        $id = (int)($q['id'] ?? 0);
        $priorFamily = (string)($q['__family'] ?? '');
        if ($id >= 3100 && $id <= 3300) {
            // Batch617 documents independent recomputation for every one of these 201 records.
            $leaf=(string)($q['taxonomy']['subcompetency_id']??$q['taxonomy']['concept_id']??'ree-unmapped');
            $sem = ['numeric_context'=>true,'class'=>'CALCULATION_REQUIRED','calculation_required'=>true,
                'family'=>$priorFamily !== '' ? 'b617:' . $leaf . ':' . $priorFamily : 'b617:' . $leaf . ':unmapped','family_leaf'=>$leaf];
            $tagged++;
            $recomputed++;
        } elseif ($id >= 1569 && $id <= 1688) {
            $sem = b638_legacy_semantics($q);
            $legacy++;
            $reviewed++;
        } else continue;
        $q['numeric'] = $sem['numeric_context'];
        $q['calculation_required'] = $sem['calculation_required'];
        $q['quantitative_semantics'] = $sem['class'];
        $q['calculation_family'] = $sem['calculation_required'] ? $sem['family'] : null;
        $q['batch638_quantitative_normalization'] = [
            'review'=>'REVIEWED','basis'=>$id >= 3100 ? 'BATCH617_INDEPENDENT_RECOMPUTATION_PRESERVED' : 'BATCH638_STEM_ANSWER_EXPLANATION_REVIEW',
            'semantic_class'=>$sem['class'],'numeric_context'=>$sem['numeric_context'],
            'calculation_required'=>$sem['calculation_required'],'calculation_family'=>$q['calculation_family'],
        ];
        if ($id >= 1569 && $id <= 1688 && $sem['calculation_required']) $q['batch638_quantitative_normalization']['legacy_recomputation'] = 'REQUIRED_BEFORE_FINAL_GATE';
        $classes[$sem['class']] = ($classes[$sem['class']] ?? 0) + 1;
        if ($q['calculation_family'] !== null) $families[$q['calculation_family']] = ($families[$q['calculation_family']] ?? 0) + 1;
    }
    unset($q);
    return ['legacy_records_reviewed'=>$reviewed,'legacy_untagged_total'=>$legacy,'prior_b617_records'=>$tagged,
        'prior_verified_recomputed'=>$recomputed,'classes'=>$classes,'families'=>count($families),
        'max_family'=>$families === [] ? 0 : max($families),'calculation_records'=>$classes['CALCULATION_REQUIRED']+$classes['MIXED_INTERPRETIVE']];
}

