    ];
    $byId=[]; foreach ($questions as $i=>$q) if (($q['board']??'')===B638_BOARD) $byId[(int)$q['id']]=$i;
    $checked=[];$failed=[];
    foreach ($expected as $id=>$value) {
        if (!isset($byId[$id])) { $failed[]=['id'=>$id,'reason'=>'MISSING_QUESTION']; continue; }
        $i=$byId[$id]; $q=&$questions[$i];
        $matches=trim((string)($q['answer']??''))===trim($value);
        $q['batch638_quantitative_normalization']['legacy_recomputation']=['status'=>$matches?'PASS':'FAIL','independent_expected_answer'=>$value,'method_family'=>$q['calculation_family']??'UNMAPPED','review_basis'=>'manual independent calculation from stem quantities and stated model'];
        if ($matches) $checked[]=$id; else $failed[]=['id'=>$id,'expected'=>$value,'actual'=>$q['answer']??null];
