    return ['required_legacy_calculation_count'=>count($required),'recomputed'=>count($checked),'failures'=>$failed,'uncovered_ids'=>$uncovered,'gate'=>count($required)===count($checked)&&$failed===[]&&$uncovered===[]?'PASS':'FAIL'];
}

function b638_fix_reviewed_defects(array &$questions): array
{
    $fixes = [];
    foreach ($questions as &$q) {
        $id = (int)($q['id'] ?? 0);
        if ($id === 1680) {
            $q['question'] = 'In a simplified equipment-selection exercise, all other conditions are satisfied and an interrupting rating must be at least the prospective fault current. For a 12 kA estimate, which listed rating is the minimum adequate value?';
            $q['answer'] = '12 kA';
            $q['explanation'] = 'The stated rule is “at least,” so equality meets the simplified criterion. The 12 kA option is the smallest rating not below the 12 kA prospective current; actual equipment selection also requires applicable current code and system checks.';
            $q['numeric'] = true;
            $q['calculation_required'] = false;
            $q['quantitative_semantics'] = 'CONCEPTUAL_QUANTITATIVE';
            $q['source_sensitivity'] = 'VERSION_SENSITIVE';
            $q['updatedAt'] = '2026-10-01T00:00:00+00:00';
            $fixes[] = ['id'=>1680,'type'=>'ANSWER_KEY_AND_EXPLANATION','before'=>'15 kA','after'=>'12 kA','reason'=>'The stem asks minimum adequate; 12 kA meets the >= criterion explicitly stated in repaired stem.'];
        }
        if ($id === 1634) {
            $q['question'] = 'Three heat-exchanger runs show inlet-to-outlet temperature rises of 20 K (A), 30 K (B), and 25 K (C). Which run has the greatest rise?';
            $q['explanation'] = 'Compare the stated rises directly: 30 K is greater than 25 K and 20 K, so Run B has the greatest temperature rise.';
            $q['numeric'] = true;
            $q['calculation_required'] = false;
            $q['quantitative_semantics'] = 'CONCEPTUAL_QUANTITATIVE';
            $q['updatedAt'] = '2026-10-01T00:00:00+00:00';
            $fixes[] = ['id'=>1634,'type'=>'MISSING_DATA_IN_STEM','reason'=>'Added the three values referenced only in the former explanation.'];
        }
    }
    unset($q);
    return $fixes;
}

function b638_review_metadata(array &$questions): void
{
    $ids = [1637,1638,1639,1679,1680,1681,1686,1687];
    $classes = [1637=>'CONCEPTUAL_QUANTITATIVE',1638=>'CURRENT_AND_SUPPORTED',1639=>'CURRENT_AND_SUPPORTED',1679=>'CURRENT_AND_SUPPORTED',1680=>'CURRENT_AND_SUPPORTED_AFTER_STEM_REPAIR',1681=>'CURRENT_AND_SUPPORTED',1686=>'CURRENT_AND_SUPPORTED',1687=>'CURRENT_AND_SUPPORTED'];
    foreach ($questions as &$q) {
        $id = (int)($q['id'] ?? 0);
        if (!in_array($id,$ids,true)) continue;
        $q['batch638_version_review'] = ['status'=>'REVIEWED','classification'=>$classes[$id],
            'reviewed_at'=>'2026-10-01','authority_ids'=>match($id) {
                1638=>['ra-11058-occupational-safety','dole-bwc-workplace-electrical-safety'],
