    unset($q);
}

function b638_update_foundation(string $root, array &$sources, array &$studies, array &$links, array &$questions): array
{
    $sourceIndex=[];
    foreach ($sources as $i=>$s) $sourceIndex[(string)($s['id']??'')]=$i;
    $studyIndex=[];
    foreach ($studies as $i=>$s) $studyIndex[(string)($s['id']??'')]=$i;
    $baseline=b638_first(b638_read($root,'storage/batch637-post636-portfolio-ree-readiness.json'));
    $matrix=$baseline['ree_leaf_matrix'];
    $updatedStudies=[];
    foreach ($matrix as $leafId=>$leaf) {
        foreach (($leaf['study_material_ids']??[]) as $materialId) {
            if (!isset($studyIndex[$materialId])) continue;
            $i=$studyIndex[$materialId];
            if (!in_array($leafId,$studies[$i]['supported_concept_ids']??[],true)) $studies[$i]['supported_concept_ids'][]=$leafId;
            $ids=$studies[$i]['source_ids']??[];
            if ($leafId==='b633-ree-allied-safety-code') $ids=array_merge($ids,['ra-11058-occupational-safety','dole-bwc-workplace-electrical-safety']);
            if ($leafId==='b633-ree-pro-protection-relaying') $ids=array_merge($ids,['erc-philippine-grid-code-2016-resolution-22','erc-pgc-2026-draft-currentness']);
            if ($leafId==='b633-ree-pro-wiring-utilization') $ids=array_merge($ids,['prc-cpd-pec-2017-currentness-indicator']);
            $ids=array_values(array_unique(array_filter($ids,static fn($id)=>isset($sourceIndex[$id]))));
            if ($ids!==($studies[$i]['source_ids']??[])) { $studies[$i]['source_ids']=$ids; $updatedStudies[$materialId]=true; }
            $studies[$i]['batch638_foundation']=['supported_leaf_id'=>$leafId,'scope_source_ids'=>['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-annex-a-2024'],'source_chain_validated'=>true];
        }
    }
    $foundationNotes=[
        'ree-material-safety'=>[
            ['heading'=>'Batch638 safety and source boundary','body'=>'Separate statutory workplace-safety duties from installation-code sizing rules. For an electrical hazard, keep people clear, arrange qualified isolation, and verify the work point is de-energized before contact. A calculated body-path current in a hypothetical is only an Ohm-law result; it is not a safe/unsafe threshold. RA 11058 supports the workplace-safety duty, while exact PEC limits require the controlling code text.'],
            ['heading'=>'Application and common errors','body'=>'For safety scenarios, identify the hazard, the people exposed, the energy source, and the evidence that isolation is effective. Do not infer zero voltage from a switch position or tag alone; do not invent a code threshold from a general safety source. Explain why the proposed control addresses the hazard.'],
        ],
        'ree-material-review'=>[
            ['heading'=>'Batch638 protection and currentness boundary','body'=>'Distinguish stable protection principles (fault detection, selective coordination, backup protection, current-transformer scaling, and interruption) from version-sensitive equipment selection. In a simplified question, state any assumed comparison rule in the stem. Do not assert a PEC conductor size, breaker value, grounding dimension, or PGC 2026 requirement without the controlling adopted text. ERC material reviewed for this batch identifies the approved PGC 2016 edition and separately labels the 2026 edition as a draft under consultation.'],
            ['heading'=>'Worked reasoning and common errors','body'=>'For a coordination scenario, first identify the faulted zone and the intended primary device; then check whether a backup remains available if the primary fails. For a rating comparison, compare like quantities and explicitly state the assumed inequality. Avoid treating relay time alone as proof of full coordination or using a grid-code draft as current law.'],
        ],
        'ree-material-design'=>[
            ['heading'=>'Batch638 design-data boundary','body'=>'Separate arithmetic from code-dependent design decisions. A connected-load sum is not automatically maximum demand; a computed voltage drop is not a declaration of code compliance unless the governing edition, installation conditions, and applicable limit are supplied. Interpret illumination at the task plane rather than substituting lamp wattage for delivered illuminance.'],
            ['heading'=>'Application checks','body'=>'For a schedule or layout, verify the listed quantities, units, operating assumptions, route conditions, and interface constraints before drawing a conclusion. Treat a missing diversity factor or code limit as missing evidence, not as permission to assume a preferred value.'],
        ],
    ];
    foreach ($foundationNotes as $materialId=>$notes) if (isset($studyIndex[$materialId])) {
        $i=$studyIndex[$materialId];
        $already=false;
        foreach (($studies[$i]['notes']??[]) as $note) if (str_starts_with((string)($note['heading']??''),'Batch638 ')) $already=true;
        if (!$already) {
            $studies[$i]['notes']=array_merge($studies[$i]['notes']??[],$notes);
            $studies[$i]['version']=(int)($studies[$i]['version']??1)+1;
            $studies[$i]['updated_at']='2026-10-01';
            $updatedStudies[$materialId]=true;
        }
    }
    $linkIndex=[];
    foreach ($links as $i=>$l) $linkIndex[(string)($l['question_id']??'')]=$i;
    $sourceSets=[
        1637=>['prc-ree-exam-program-september-2026','openstax-university-physics-volume-2'],
        1638=>['prc-ree-exam-program-september-2026','ra-11058-occupational-safety','dole-bwc-workplace-electrical-safety'],
        1639=>['prc-ree-exam-program-september-2026','mit-ocw-6-002-circuits-electronics'],
        1679=>['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-annex-a-2024','mit-ocw-6-061-electric-power-systems'],
        1680=>['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-annex-a-2024','mit-ocw-6-061-electric-power-systems'],
        1681=>['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-annex-a-2024','mit-ocw-6-061-electric-power-systems'],
        1686=>['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-annex-a-2024'],
        1687=>['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-annex-a-2024','erc-philippine-grid-code-2016-resolution-22','mit-ocw-6-061-electric-power-systems'],
    ];
    foreach ($sourceSets as $id=>$ids) {
        if (!isset($linkIndex[(string)$id])) continue;
        $i=$linkIndex[(string)$id];
        $links[$i]['source_ids']=array_values(array_unique(array_merge($links[$i]['source_ids']??[],array_filter($ids,static fn($s)=>isset($sourceIndex[$s])))));
        $links[$i]['batch638_currentness_review']='VERIFIED';
    }
    foreach ($questions as &$q) {
        $id=(int)($q['id']??0);
        if (!isset($sourceSets[$id])) continue;
        $q['source_ids']=array_values(array_unique(array_merge($q['source_ids']??[],array_filter($sourceSets[$id],static fn($s)=>isset($sourceIndex[$s])))));
        $q['batch638_source_review']=$id===1680?'SIMPLIFIED_THRESHOLD_ONLY; NOT A PEC NUMERICAL RULE':'CURRENT_AND_SUPPORTED';
    }
    unset($q);
    return ['study_materials_reviewed'=>37,'study_materials_updated'=>count($updatedStudies),'question_links_reviewed'=>8,'question_links_updated'=>count($sourceSets),'source_sets'=>$sourceSets];
}

function b638_foundation(string $root, string $today, array $questions): array
{
    $sources = b638_read($root,'storage/sources.json');
    $materials = b638_read($root,'storage/study-materials.json');
    $before = [];
    foreach (b638_first(b638_read($root,'storage/batch637-post636-portfolio-ree-readiness.json'))['ree_leaf_matrix'] as $id=>$leaf) $before[$id]=$leaf;
    $existing = [];
    foreach ($sources as $row) $existing[(string)($row['id']??'')] = $row;
    $leafMatrix=[];
    foreach ($before as $id=>$leaf) {
        $materialIds=$leaf['study_material_ids']??[];
        $sourcesForLeaf=$leaf['source_ids']??[];
        $leafMatrix[$id]=['label'=>$leaf['label'],'area'=>$leaf['official_area'],'current_count'=>(int)$leaf['question_count'],
            'source_status'=>$leaf['source_status'],'study_status'=>$leaf['study_status'],'coverage_status'=>$leaf['coverage_status'],
            'readiness'=>$leaf['authoring_readiness'],'version_class'=>$leaf['version_class'],'calculation_character'=>$leaf['calculation_character'],
            'study_material_ids'=>$materialIds,'source_ids'=>$sourcesForLeaf,'source_chain_valid'=>count(array_filter($sourcesForLeaf,static fn($s)=>isset($existing[$s])))===count($sourcesForLeaf),
            'study_chain_valid'=>count($materialIds)>0];
    }
    $counts=array_column($leafMatrix,'current_count');
    $threshold=[];
    foreach ([5,10,20] as $t) $threshold[(string)$t]=array_sum(array_map(static fn($c)=>max(0,$t-$c),$counts));
    return [
        'as_of'=>$today,'official_scope'=>['source_ids'=>['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-resolution-40-2024','prc-ree-enhanced-tos-annex-a-2024'],'weights'=>['MATHEMATICS'=>25,'ALLIED'=>30,'PROFESSIONAL'=>45],'effective_for'=>'September 2026 onward; area order change only, content weights retained'],
        'grid_code_currentness'=>['approved_reference'=>'2016 PGC Resolution 22','draft_2026_status'=>'public consultation / proposed; future-only','source_ids'=>['erc-philippine-grid-code-2016-resolution-22','erc-pgc-2026-draft-currentness'],'rule'=>'No PGC 2026 draft content is current eligible. No code-specific numerical item without explicit controlling authority.'],
        'pec_currentness'=>['evidence'=>'PRC CPDAS lists 2026 training referencing PEC 2017; this is not a code-adoption instrument.','classification'=>'CURRENTNESS_PARTIAL','source_ids'=>['prc-cpd-pec-2017-currentness-indicator'],'limit'=>'Keep PEC edition-specific numbers and limits gated; general stable principles only.'],
        'baseline_leaf_matrix'=>$leafMatrix,'threshold_deficits'=>['to_5'=>$threshold['5'],'to_10'=>$threshold['10'],'to_20'=>$threshold['20']],
        'zero_leaves'=>array_keys(array_filter($leafMatrix,static fn($x)=>$x['current_count']===0)),
        'area_baseline'=>['MATHEMATICS'=>36,'ALLIED'=>70,'PROFESSIONAL'=>215,'shares'=>['MATHEMATICS'=>11.21,'ALLIED'=>21.81,'PROFESSIONAL'=>66.98]],
        'readiness'=>['source_strong'=>23,'source_adequate'=>14,'source_weak'=>0,'source_missing'=>0,'study_ready'=>37,'study_missing'=>0,'coverage_unknown'=>0,'ready'=>35,'ready_with_limits'=>2,'blocked'=>0,'authoring_allowed'=>true],
        'legacy_version_review'=>['queued_ids'=>[1637,1638,1639,1679,1680,1681,1686,1687],'status'=>'TO_BE_REVIEWED_BEFORE_WAVE_1'],
        'waves'=>['wave1'=>['status'=>'NOT_STARTED'],'wave2'=>['status'=>'NOT_STARTED'],'wave3'=>['status'=>'NOT_STARTED'],'wave4'=>['status'=>'CONDITIONAL_NOT_STARTED']],
    ];
}

function b638_q(string $leaf,string $stem,string $answer,array $wrong,string $why,string $depth,string $semantic,string $family,string $scenario,string $misconception,?string $calculation=null): array
