        b638_q('b633-ree-pro-computer-power-applications','An operations dashboard lets every user change relay settings, although most only need to view status. Which access principle reduces risk?','Grant the least privilege needed for each role',['Share one administrator account','Allow unrestricted access and audit later','Disable authentication during shifts'],'Least privilege limits each account to the access required for its work.','D3','NON_NUMERICAL','least-privilege-control','operational-cybersecurity','confuses availability with unrestricted authorization',''),
