    // Existing 1–4 cohorts: exact remaining additions needed to reach five.
    $add([
        b638_q('b633-ree-math-complex-phasors','For z=3+j4, what is |z|?','5',['7','1','25'],'|z|=√(3²+4²)=5.','D3','CALCULATION_REQUIRED','complex-magnitude','phasor-evaluation','adds components instead of vector magnitude','sqrt(3^2+4^2)=5'),
        b638_q('b633-ree-math-calculus-differential','A current is i(t)=2t² A. What is di/dt at t=3 s?','12 A/s',['6 A/s','18 A/s','36 A/s'],'Differentiate to obtain 4t; at t=3 the rate is 12 A/s.','D3','CALCULATION_REQUIRED','derivative-rate','signal-slope','uses the function value instead of its derivative','4*3=12'),
        b638_q('b633-ree-math-calculus-differential','A constant 4 A current flows for 5 s. How much charge passes?','20 C',['0.8 C','9 C','25 C'],'Q=∫i dt=It=4(5)=20 C.','D3','CALCULATION_REQUIRED','current-time-charge','charge-accumulation','divides current by time','4*5=20C'),
        b638_q('b633-ree-math-probability-statistics','A component succeeds with probability 0.9 independently on each of two tests. What is the probability both succeed?','0.81',['0.90','0.18','0.99'],'For independent events, multiply: 0.9×0.9=0.81.','D3','CALCULATION_REQUIRED','independent-joint-probability','reliability-test','adds probabilities of independent successes','0.9*0.9=0.81'),
        b638_q('b633-ree-math-discrete-economics','What is the present worth of 1,100 due one year from now at 10% annual discounting?','1,000',['990','1,210','11,000'],'P=F/(1+i)=1100/1.10=1000.','D3','CALCULATION_REQUIRED','single-payment-present-worth','engineering-economics','multiplies a future value by the discount factor denominator','1100/1.10=1000'),
        b638_q('b633-ree-math-discrete-economics','An equipment option costs 12,000 now and saves 3,000 per year for four years, ignoring time value. What is its simple net benefit?','0',['3,000','12,000','24,000'],'Total undiscounted savings are 4×3,000=12,000; subtracting the initial cost gives zero.','D3','CALCULATION_REQUIRED','simple-undiscounted-net-benefit','capital-choice','compares annual saving with total first cost','4*3000-12000=0'),
        b638_q('b633-ree-math-discrete-economics','An amount grows by 5% in one year from a base of 2,000. What is the resulting amount?','2,100',['2,005','2,500','1,900'],'The increase is 0.05(2,000)=100, giving 2,100.','D3','CALCULATION_REQUIRED','single-period-growth','cost-escalation','adds five currency units rather than five percent','2000*1.05=2100'),
        b638_q('b633-ree-math-discrete-economics','Two alternatives have equal service and risk; one has lower equivalent annual cost. Which is preferred under a cost-minimization objective?','The lower equivalent-annual-cost alternative',['The higher first cost in every case','The alternative with more years of paperwork','Neither can be compared'],'Equivalent annual cost places alternatives on a common annual basis; with equal service and risk, choose the lower cost.','D3','NON_NUMERICAL','equivalent-annual-cost-choice','life-cycle-economics','compares only initial cost',''),
        b638_q('b633-ree-allied-mechanics','A 6 kg cart accelerates at 3 m/s². What net force acts on it?','18 N',['2 N','9 N','36 N'],'Newton’s second law gives F=ma=6(3)=18 N.','D3','CALCULATION_REQUIRED','newton-second-law','inertial-response','divides mass by acceleration','6*3=18N'),
        b638_q('b633-ree-allied-mechanics','A 40 N force acts perpendicular to a 0.5 m lever arm. What moment magnitude results?','20 N·m',['80 N·m','40 N·m','0.8 N·m'],'For a perpendicular force, M=Fr=40(0.5)=20 N·m.','D3','CALCULATION_REQUIRED','force-moment-arm','mechanical-equilibrium','uses force divided by arm length','40*0.5=20Nm'),
        b638_q('b633-ree-allied-thermodynamics','How much heat is needed to raise 2 kg of material with c=500 J/(kg·K) by 4 K?','4,000 J',['250 J','1,000 J','8,000 J'],'Q=mcΔT=2(500)(4)=4,000 J.','D3','CALCULATION_REQUIRED','sensible-heat','thermal-storage','omits either mass or temperature change','2*500*4=4000J'),
        b638_q('b633-ree-allied-thermodynamics','A thermal process transfers heat from a hotter body to a cooler body without external work. Which direction is spontaneous?','From hotter to cooler',['From cooler to hotter','Both directions equally without a driver','Only from a vacuum'],'Heat flows spontaneously down a temperature gradient; moving it uphill requires external work.','D2','NON_NUMERICAL','heat-flow-direction','thermal-process','treats heat flow as reversible without a driving input',''),
        b638_q('b633-ree-allied-fluid-mechanics','A 0.02 m² piston carries a 1,000 N load. What gauge pressure is applied to the fluid?','50 kPa',['20 kPa','500 kPa','0.02 kPa'],'p=F/A=1000/0.02=50,000 Pa=50 kPa.','D3','CALCULATION_REQUIRED','force-area-pressure','hydraulic-actuation','uses area multiplied by force','1000/0.02=50000Pa'),
        b638_q('b633-ree-allied-fluid-mechanics','For steady incompressible flow through a narrowing horizontal pipe, what happens to average speed if flow rate is conserved?','It increases in the smaller area',['It decreases in the smaller area','It remains constant regardless of area','It becomes zero'],'Continuity requires Av to remain constant, so smaller area means greater average speed.','D3','CONCEPTUAL_QUANTITATIVE','continuity-area-velocity','pipe-flow','assumes velocity is independent of area',''),
        b638_q('b633-ree-allied-safety-code','A technician finds a lockout tag but has not verified the circuit is de-energized. What should happen before work begins?','Verify absence of voltage with a suitable instrument',['Assume the tag proves zero voltage','Touch the conductor briefly','Rely only on a panel indicator'],'A tag communicates status but does not itself prove absence of hazardous voltage at the work point.','D3','NON_NUMERICAL','verify-deenergized-state','safe-work-isolation','confuses administrative indication with test evidence',''),
        b638_q('b633-ree-allied-safety-code','A worker reports a damaged insulating barrier near exposed live parts. What is the appropriate immediate response?','Keep people clear and have the hazard isolated and assessed by qualified personnel',['Cover it with paper and continue','Ask an unqualified person to repair it live','Ignore it if no one has been injured'],'Restrict access and arrange qualified hazard control; do not improvise a repair near exposed energized parts.','D4','NON_NUMERICAL','electrical-hazard-containment','workplace-hazard','waits for an injury before controlling a hazard',''),
        b638_q('b633-ree-pro-generators-conversion','A generator converts mechanical input into what output form?','Electrical energy',['Chemical energy only','Heat with no electrical output','Mass flow'],'Electromagnetic induction converts mechanical energy supplied at the shaft into electrical energy at the terminals, with losses.','D2','NON_NUMERICAL','generator-energy-conversion','machine-energy-flow','ignores the mechanical input and losses',''),
        b638_q('b633-ree-pro-generators-conversion','A generator receives 12 kW mechanical input and delivers 10.8 kW electrical output. What is its efficiency?','90%',['80%','92%','111%'],'η=output/input=10.8/12=0.90=90%.','D3','CALCULATION_REQUIRED','generator-efficiency','conversion-performance','reverses input and output','10.8/12=0.90'),
        b638_q('b633-ree-pro-transients','After a long time on DC, an ideal capacitor behaves as what in a steady-state circuit?','An open circuit',['A short circuit','A current source of infinite value','A resistor equal to its capacitance'],'At DC steady state, capacitor voltage is constant, so i=C dv/dt=0.','D3','NON_NUMERICAL','capacitor-dc-steady-state','transient-settling','confuses the instant of switching with long-time behavior',''),
        b638_q('b633-ree-pro-wiring-utilization','A lighting layout has 12 fixtures rated 20 W each. What is their connected real load before any demand adjustment?','240 W',['32 W','120 W','2,400 W'],'Connected load is the sum of fixture ratings: 12×20=240 W. This is not a code demand calculation.','D3','CALCULATION_REQUIRED','connected-lighting-load','lighting-schedule','applies a demand factor not supplied','12*20=240W'),
        b638_q('b633-ree-pro-wiring-utilization','A room is too dim even though each luminaire operates. Which design quantity is most directly checked at the task plane?','Illuminance',['Power factor','Conductor resistivity','Transformer turns ratio'],'Illuminance measures luminous flux incident per area at the working surface.','D3','NON_NUMERICAL','illumination-performance','workplane-assessment','uses lamp electrical input as a substitute for delivered light',''),
        b638_q('b633-ree-pro-wiring-utilization','A load schedule lists 3 kW, 2 kW, and 5 kW. What is the arithmetic connected-load total?','10 kW',['5 kW','8 kW','30 kW'],'Add the listed connected loads: 3+2+5=10 kW. No diversity assumption is applied.','D3','CALCULATION_REQUIRED','connected-load-sum','load-schedule','confuses sum with maximum demand','3+2+5=10kW'),
        b638_q('b633-ree-pro-wiring-utilization','A drawing shows a conductor route crossing a sharp metal edge. Which design review concern is most direct?','Mechanical protection and insulation damage risk',['Power-factor correction','Frequency synchronization','Transformer polarity'],'A sharp edge can abrade insulation; routing and suitable protection must prevent mechanical damage.','D3','NON_NUMERICAL','wiring-mechanical-protection','installation-review','reviews only electrical rating and ignores physical routing',''),
        b638_q('b633-ree-pro-protection-relaying','A primary relay should operate before its backup for a fault in the primary zone. What is the purpose of that time separation?','Selective coordination',['Increasing fault current','Reducing system frequency','Preventing all protective devices from operating'],'Coordination lets the device closest to the fault clear first while backup protection remains available.','D3','NON_NUMERICAL','relay-selectivity','protection-coordination','expects all breakers to trip at once',''),
        b638_q('b633-ree-pro-control-systems','A negative-feedback system has reference r and measured output y. What signal is normally compared at the summing junction?','The error r−y',['The product r y only','The derivative of the plant input','The output added to itself'],'Negative feedback forms an error by subtracting measured output from the reference.','D2','NON_NUMERICAL','feedback-error-signal','control-loop','reverses the feedback sign',''),
        b638_q('b633-ree-pro-control-systems','A stable first-order system has time constant τ=0.5 s. Approximately how long is needed to reach 63.2% of a step response?','0.5 s',['0.25 s','1.0 s','5.0 s'],'A first-order step response reaches 1−e⁻¹≈63.2% at t=τ.','D3','CONCEPTUAL_QUANTITATIVE','first-order-time-constant','dynamic-response','confuses one time constant with full settling',''),
        b638_q('b633-ree-pro-power-electronics','An ideal boost converter operates in continuous conduction. What happens to the output relative to input for duty ratio 0<D<1?','Output is greater than input',['Output is lower than input','Output equals zero','Output polarity must reverse'],'For the ideal boost relation Vout=Vin/(1−D), the output exceeds the input for 0<D<1.','D3','CONCEPTUAL_QUANTITATIVE','boost-converter-ratio','dc-conversion','uses the buck relation for a boost stage',''),
        b638_q('b633-ree-pro-power-electronics','A switching device dissipates power during both its on-state and switching transitions. What can reduce switching loss at fixed device and load?','Reducing switching frequency, subject to ripple and size constraints',['Increasing switching frequency without limit','Increasing transition time','Shorting the output'],'Fewer transitions per second generally reduce switching loss, but can increase ripple or require larger passive components.','D4','NON_NUMERICAL','switching-loss-tradeoff','converter-design','optimizes one loss term without considering ripple',''),
        b638_q('b633-ree-pro-power-electronics','A rectifier output contains a DC component and periodic ripple. Which addition most directly smooths the output?','A properly selected filter element',['A series switch held open','A second uncontrolled AC source','A smaller load resistance in every case'],'A filter stores and releases energy to reduce output variation; component choice depends on load and ripple requirements.','D3','NON_NUMERICAL','rectifier-filtering','power-conversion','assumes rectification alone produces perfectly constant DC',''),
    ]);
    return $q;
}

function b638_wave2_blueprints(): array
