        b638_q('b633-ree-allied-mechanics','A 12 kg cart moves at 3 m/s. What is its linear momentum?','36 kg·m/s',['4 kg·m/s','15 kg·m/s','108 kg·m/s'],'Momentum p=mv=12(3)=36 kg·m/s.','D3','CALCULATION_REQUIRED','linear-momentum','mechanical-state','uses kinetic-energy relation instead','12*3=36'),
        b638_q('b633-ree-allied-mechanics','A 2 kg mass falls from rest through 5 m, neglecting losses and using g=10 m/s². What speed does energy conservation predict?','10 m/s',['5 m/s','20 m/s','50 m/s'],'mgh=½mv² gives v=√(2gh)=√100=10 m/s.','D3','CALCULATION_REQUIRED','gravitational-energy-speed','energy-method','uses gh without the factor 2 under the square root','sqrt(2*10*5)=10'),
