        b638_q('b633-ree-allied-mechanics','A body is in static equilibrium. What must be true of the net force and net moment?','Both are zero',['Only net force is zero','Only net moment is zero','Both are nonzero but equal'],'Static equilibrium requires translational and rotational equilibrium.','D2','NON_NUMERICAL','rigid-body-equilibrium','support-reaction','checks force balance but ignores rotation',''),
