        b638_q('b633-ree-allied-mechanics','Work by a constant force is zero when the force is what relative to displacement?','Perpendicular',['Parallel','At 45°','In the direction of motion'],'W=Fd cosθ; at 90°, cosθ=0.','D2','CONCEPTUAL_QUANTITATIVE','work-angle','energy-transfer','assumes any applied force does work along displacement',''),
