        b638_q('b633-ree-allied-mechanics','A 5 kg body is lifted at constant speed. What is the net vertical force on it?','Zero',['49 N upward','49 N downward','5 N upward'],'Constant velocity means zero acceleration, so applied lift balances weight and net force is zero.','D3','NON_NUMERICAL','constant-speed-force-balance','lifting-load','equates the applied force with net force',''),
