        b638_q('b633-ree-allied-materials','A 30 kN tensile load acts on a 300 mm² bar. What is average normal stress?','100 MPa',['10 MPa','90 MPa','1 MPa'],'30,000 N/300 mm²=100 N/mm²=100 MPa.','D3','CALCULATION_REQUIRED','axial-stress','material-response','fails to convert kN to N','30000/300=100N/mm2'),
