        b638_q('b633-ree-math-discrete-economics','An annual cost is 2,000 for each of six years. Ignoring discounting, what is the total?','12,000',['8,000','6,000','2,006'],'Six equal annual costs total 6×2,000=12,000.','D3','CALCULATION_REQUIRED','uniform-cost-undiscounted-sum','maintenance-cost','adds the number of years to the payment','6*2000=12000'),
