        b638_q('b633-ree-math-trigonometry-analytic-geometry','The angle between two vectors is 0°. What is their dot product in terms of magnitudes A and B?','AB',['0','−AB','A+B'],'A·B=AB cosθ; at zero degrees cosθ=1.','D3','CONCEPTUAL_QUANTITATIVE','dot-product-alignment','vector-projection','treats aligned vectors as perpendicular',''),
        b638_q('b633-ree-math-trigonometry-analytic-geometry','A circle has radius 3. What is its circumference?','6π',['3π','9π','π'],'Circumference is 2πr=6π.','D2','CALCULATION_REQUIRED','circle-circumference','geometric-measure','uses area formula instead of circumference','2*pi*3=6pi'),
