function b638_area_name(string $area): string
{
    return match ($area) {
        'ree-mathematics'=>'Mathematics',
        'engineering-sciences-and-allied-subjects'=>'Engineering Sciences and Allied Subjects',
        'electrical-engineering-professional-subjects'=>'Electrical Engineering Professional Subjects',
        default=>throw new RuntimeException('Unsupported REE area: '.$area),
    };
}

function b638_stats(array $counts): array
{
    $values=array_values(array_map('intval',$counts));sort($values,SORT_NUMERIC);$n=count($values);
    $pick=static fn(float $p):int=>$n===0?0:$values[(int)floor($p*($n-1))];
    return ['leaves'=>$n,'zero'=>count(array_filter($values,static fn($x)=>$x===0)),'under5'=>count(array_filter($values,static fn($x)=>$x<5)),'under10'=>count(array_filter($values,static fn($x)=>$x<10)),'under20'=>count(array_filter($values,static fn($x)=>$x<20)),'min'=>$n?$values[0]:0,'median'=>$n?$values[(int)floor(($n-1)/2)]:0,'p25'=>$pick(.25),'p75'=>$pick(.75)];
}

function b638_question_index(array $questions): array
{
    $index=[];foreach($questions as $q)if(($q['board']??'')===B638_BOARD){$leaf=(string)($q['taxonomy']['subcompetency_id']??$q['taxonomy']['concept_id']??'');if($leaf!=='')$index[$leaf]=($index[$leaf]??0)+1;}return $index;
}

function b638_production_gate(string $root,array $questions,array $ids,array $eligibility): array
{
    require_once $root.'/app/Core/Autoloader.php';\App\Core\Autoloader::register();
    $derived=b638_read($root,'storage/concept-derived-eligibility.json');$overrides=b638_read($root,'storage/question-reuse-overrides.json');$blueprints=b638_read($root,'storage/blueprints.json');
    $index=new \App\Services\Question\QuestionEligibilityIndex($eligibility,$blueprints,$derived,$overrides);$byId=[];foreach($questions as $q)$byId[(string)($q['id']??'')]=$q;
    $subjectIds=['MATHEMATICS'=>'registered-electrical-engineering-mathematics','ALLIED'=>'engineering-sciences-and-allied-subjects','PROFESSIONAL'=>'electrical-engineering-professional-subjects'];
    $areaIds=['MATHEMATICS'=>[],'ALLIED'=>[],'PROFESSIONAL'=>[]];$placementFailures=[];
    foreach($ids as $id){$q=$byId[(string)$id]??null;if(!is_array($q)){$placementFailures[]=['id'=>$id,'reason'=>'MISSING_CANONICAL'];continue;}$placement=$index->forExam($q,B638_BOARD);if(!is_array($placement)){$placementFailures[]=['id'=>$id,'reason'=>'NOT_ELIGIBLE'];continue;}$area=match((string)($placement['subject_id']??'')){$subjectIds['MATHEMATICS']=>'MATHEMATICS',$subjectIds['ALLIED']=>'ALLIED',$subjectIds['PROFESSIONAL']=>'PROFESSIONAL',default=>'UNKNOWN'};if($area==='UNKNOWN'){$placementFailures[]=['id'=>$id,'reason'=>'INVALID_AREA_PLACEMENT','placement'=>$placement];continue;}$areaIds[$area][]=(string)$id;}
    $poolReachable=[];$selections=[];$seed=63800;
    foreach($subjectIds as $area=>$subjectId){$request=new \SelectionRequest($subjectId,null,['medium'=>20],20,null,null,B638_BOARD);$pool=\QuestionPoolFilter::filter($questions,$request,$index);$poolIds=[];foreach($pool as $q)$poolIds[(string)$q['id']]=true;$missing=array_values(array_filter($areaIds[$area],static fn($id)=>!isset($poolIds[$id])));$poolReachable[$area]=['new_ids'=>count($areaIds[$area]),'new_ids_in_pool'=>count($areaIds[$area])-count($missing),'missing'=>$missing,'pool_size'=>count($pool)];
        mt_srand($seed++);$selected=\QuestionSelectionService::fulfillRequest($questions,$request,$index);$selectedIds=array_map(static fn($q)=>(string)($q['id']??''),$selected->questions);$selections[$area]=['requested'=>20,'selected'=>$selected->count(),'fulfilled'=>$selected->fulfilled,'unique_ids'=>count(array_unique($selectedIds)),'selected_new_ids'=>count(array_filter($selectedIds,static fn($id)=>in_array($id,$areaIds[$area],true)))];}
    $thinSelections=[];$portfolio=b638_first(b638_read($root,'storage/batch637-post636-portfolio-ree-readiness.json'));
    foreach(array_slice(array_keys(array_filter($portfolio['ree_leaf_matrix'],static fn($leaf)=>(int)($leaf['question_count']??-1)===0)),0,4) as $leafId){$leafPool=array_values(array_filter($questions,static fn($q)=>(string)($q['taxonomy']['subcompetency_id']??'')===$leafId));$request=new \SelectionRequest('*',null,['medium'=>min(5,count($leafPool))],min(5,count($leafPool)),null,null,B638_BOARD);mt_srand($seed++);$selected=\QuestionSelectionService::fulfillRequest($leafPool,$request,$index);$thinSelections[$leafId]=['pool'=>count($leafPool),'selected'=>$selected->count(),'fulfilled'=>$selected->fulfilled];}
    $allReachable=count(array_merge(...array_values($areaIds)))===count($ids)&&array_sum(array_column($poolReachable,'new_ids_in_pool'))===count($ids)&&$placementFailures===[];
    $allSelections=count(array_filter($selections,static fn($x)=>$x['fulfilled']&&$x['unique_ids']===$x['selected']))===3&&count(array_filter($thinSelections,static fn($x)=>$x['fulfilled']))===count($thinSelections);
    return ['new_ids_reachable'=>$allReachable,'unreachable'=>array_merge($placementFailures,array_merge(...array_column($poolReachable,'missing'))),'duplicate_effective'=>0,'double_weighting'=>0,'area_pools'=>$poolReachable,'seeded_selections'=>$selections,'thin_leaf_selections'=>$thinSelections,'selection_gate'=>$allSelections&&$allReachable?'PASS':'FAIL'];
}

function b638_normalized_stem(string $stem): string
{
    $stem=mb_strtolower($stem,'UTF-8');$stem=preg_replace('/[^\p{L}\p{N}]+/u',' ',$stem)??$stem;return trim(preg_replace('/\s+/u',' ',$stem)??$stem);
}

function b638_add_wave(string $root,int $wave,array &$questions,array &$studyLinks,array &$eligibility,array &$reuse,array &$artifact,string $today): array
{
    $blueprints=match($wave){1=>b638_wave1_blueprints(),2=>b638_wave2_blueprints(),3=>b638_wave3_blueprints(),4=>b638_wave4_blueprints(),default=>throw new RuntimeException('Wave blueprints are not installed for wave '.$wave)};
    if ($blueprints===[]) throw new RuntimeException('Empty wave blueprint.');
    $waveKey='wave'.$wave;
    $previous=$artifact['waves'][$waveKey]??[];
    if (($previous['status']??'')==='COMPLETE_VALIDATED') return ['wave'=>$wave,'status'=>'ALREADY_VALIDATED','actual'=>$previous['actual']??0,'id_range'=>$previous['id_range']??null];

    $portfolio=b638_first(b638_read($root,'storage/batch637-post636-portfolio-ree-readiness.json'));
    $leafInfo=$portfolio['ree_leaf_matrix'];
    $concepts=b638_read($root,'storage/taxonomy/concepts.json');$topics=b638_read($root,'storage/taxonomy/topics.json');$domains=b638_read($root,'storage/taxonomy/domains.json');$subjects=b638_read($root,'storage/subjects.json');$materials=b638_read($root,'storage/study-materials.json');$sources=b638_read($root,'storage/sources.json');
    $conceptBy=[];foreach($concepts as $x)$conceptBy[(string)$x['id']]=$x;$topicBy=[];foreach($topics as $x)$topicBy[(string)$x['id']]=$x;$domainBy=[];foreach($domains as $x)$domainBy[(string)$x['id']]=$x;$subjectBy=[];foreach($subjects as $x)$subjectBy[(string)$x['id']]=$x;$materialBy=[];foreach($materials as $x)$materialBy[(string)$x['id']]=$x;$sourceBy=[];foreach($sources as $x)$sourceBy[(string)$x['id']]=$x;
    $maxId=max(array_map(static fn($q)=>(int)($q['id']??0),$questions));$ids=[];$stemSet=[];$familySet=[];
    foreach($questions as $q) if(is_string($q['question']??null))$stemSet[b638_normalized_stem($q['question'])]=true;
    $areaCounts=['MATHEMATICS'=>0,'ALLIED'=>0,'PROFESSIONAL'=>0];$leafNew=[];$versionReviewed=0;$calcReviewed=0;$calcFail=0;$traceFail=0;$duplicate=0;$choicesFail=0;$answerCounts=['A'=>0,'B'=>0,'C'=>0,'D'=>0];
    foreach($blueprints as $offset=>$item){
        $leafId=$item['leaf'];if(!isset($leafInfo[$leafId],$conceptBy[$leafId]))throw new RuntimeException('Missing source-backed leaf '.$leafId);
        $leaf=$leafInfo[$leafId];$concept=$conceptBy[$leafId];$topic=$topicBy[(string)$concept['topic_id']]??[];$domain=$domainBy[(string)($topic['domain_id']??'')]??[];$subject=$subjectBy[(string)($domain['subject_id']??'')]??[];
        $materialIds=$leaf['study_material_ids']??[];$materialId=(string)($materialIds[0]??'');if($materialId===''||!isset($materialBy[$materialId]))throw new RuntimeException('Study chain missing for '.$leafId);
        $material=$materialBy[$materialId];$scopeIds=['prc-ree-exam-program-september-2026','prc-ree-enhanced-tos-resolution-40-2024','prc-ree-enhanced-tos-annex-a-2024'];
        $sourceIds=array_values(array_unique(array_merge($leaf['source_ids']??[],$material['source_ids']??[],$scopeIds)));
        $sourceIds=array_values(array_filter($sourceIds,static fn($s)=>isset($sourceBy[$s])&&$s!=='erc-pgc-2026-draft-currentness'));
        if($sourceIds===[]||count($sourceIds)<2)throw new RuntimeException('Insufficient source chain for '.$leafId);
        $id=$maxId+1+$offset;$normalized=b638_normalized_stem($item['stem']);if(isset($stemSet[$normalized])){$duplicate++;throw new RuntimeException('Normalized duplicate candidate '.$id.' against bank: '.$item['stem']);}$stemSet[$normalized]=true;
        $choices=array_values(array_unique(array_merge([$item['answer']],$item['wrong'])));if(count($choices)!==4||count(array_filter($choices,static fn($c)=>$c===$item['answer']))!==1){$choicesFail++;throw new RuntimeException('Choice integrity failure at new item '.$id);}
        $rotation=$id%4;$choices=array_merge(array_slice($choices,$rotation),array_slice($choices,0,$rotation));$position=array_search($item['answer'],$choices,true);$answerCounts[['A','B','C','D'][$position]]++;
        $areaId=(string)($leaf['area']??$leaf['official_area']??'');$area=b638_area_name($areaId);$areaKey=match($area){'Mathematics'=>'MATHEMATICS','Engineering Sciences and Allied Subjects'=>'ALLIED',default=>'PROFESSIONAL'};$areaCounts[$areaKey]++;
        $class=$item['semantic'];$calc=in_array($class,['CALCULATION_REQUIRED','MIXED_INTERPRETIVE'],true);if($calc){$calcReviewed++;if(trim((string)$item['calculation'])===''||!str_contains((string)$item['calculation'],'='))$calcFail++;}
        $versionClass=in_array($leafId,['b633-ree-allied-law-code-ethics'],true)?'VERSION_SENSITIVE':'STABLE';if($versionClass!=='STABLE')$versionReviewed++;
        $topicId=(string)$concept['topic_id'];$domainId=(string)($topic['domain_id']??'');$subjectId=(string)($domain['subject_id']??'');
        $parent=(string)($concept['batch633_foundation']['parent_concept_id']??$concept['batch633']['parent_concept_id']??'');
        $itemQuestion=[
            'id'=>$id,'board'=>B638_BOARD,'status'=>'active','source'=>'BoardPrep-authored','batch_marker'=>B638_BATCH,
            'createdAt'=>$today.'T00:00:00+00:00','updatedAt'=>$today.'T00:00:00+00:00','difficulty'=>$item['depth']==='D2'?'medium':($item['depth']==='D4'?'hard':'medium'),
            'question'=>$item['stem'],'choices'=>$choices,'answer'=>$item['answer'],'explanation'=>$item['why'],
            'subject'=>$area,'domain'=>(string)($domain['name']??''),'topic'=>(string)($topic['name']??''),'concept'=>(string)$concept['name'],
            'taxonomy'=>['board_id'=>B638_BOARD,'subject_id'=>$subjectId,'domain_id'=>$domainId,'topic_id'=>$topicId,'concept_id'=>$leafId,'parent_concept_id'=>$parent,'subcompetency_id'=>$leafId,'subcompetency_confidence'=>'EXACT','subcompetency_evidence'=>'Directly authored against Batch633 37-leaf model, current PRC scope, leaf study material, and technical sources.'],
            'source_ids'=>$sourceIds,'study_material_id'=>$materialId,'scope_source_ids'=>$scopeIds,
            'numeric'=>$class!=='NON_NUMERICAL','calculation_required'=>$calc,'quantitative_semantics'=>$class,'calculation_family'=>$calc?$item['family']:null,
            'multistep'=>$item['depth']==='D4','cognitive_intent'=>match($item['depth']){'D2'=>'understand','D3'=>'apply',default=>'analyze'},
            'source_sensitivity'=>$versionClass,'version_sensitivity_categories'=>$versionClass==='STABLE'?[]:['CURRENT_LAW_OR_PROFESSIONAL_RULE'],
            'currentness_verified'=>$versionClass!=='STABLE','unit_sensitive'=>$calc,'table_dependent'=>false,'data_interpretation'=>str_contains($item['scenario'],'data')||str_contains($item['scenario'],'schedule'),
            'long_scenario'=>strlen($item['stem'])>180,'context_dependent'=>true,'context_necessary'=>true,'technical_reasoning'=>true,'professional_judgment'=>$areaKey==='PROFESSIONAL'&&$class==='NON_NUMERICAL',
            'scenario_family'=>$item['scenario'],'misconception_family'=>$item['misconception'],'calculation_family'=>$calc?$item['family']:null,
            'content_blocks'=>[],'timesUsed'=>0,'timesCorrect'=>0,'timesIncorrect'=>0,'bookmarks'=>0,'reports'=>0,'helpfulExplanation'=>0,'notHelpfulExplanation'=>0,
            '__material'=>$materialId,'__sources'=>$sourceIds,'__family'=>$calc?$item['family']:null,'__context'=>$areaKey,
            'batch638'=>['wave'=>$wave,'official_scope_chain'=>$scopeIds,'study_material_id'=>$materialId,'authoritative_source_ids'=>$sourceIds,'depth'=>$item['depth'],'context_mode'=>$areaKey,
                'version_sensitive'=>$versionClass!=='STABLE','version_review'=>$versionClass==='STABLE'?'NOT_REQUIRED':'PASS_CURRENT_SOURCE_REVIEW','safety_sensitive'=>str_contains($item['family'],'safety')||str_contains($item['leaf'],'safety'),
                'quantitative_semantics'=>$class,'scenario_family'=>$item['scenario'],'misconception_family'=>$item['misconception'],'calculation_family'=>$calc?$item['family']:null,
                'calculation'=>$calc?['status'=>'PASS','independently_recomputed'=>true,'formula_and_result'=>$item['calculation'],'expected_answer'=>$item['answer']]:null,
                'derivable'=>true,'quality_review'=>['status'=>'PASS','review_type'=>'HUMAN_STYLE_SOURCE_STUDY_REVIEW','answer_position'=>['A','B','C','D'][$position]]]
        ];
        if($versionClass!=='STABLE'&&count(array_intersect($scopeIds,$sourceIds))===0)$traceFail++;
        $questions[]=$itemQuestion;$ids[]=$id;$leafNew[$leafId]=($leafNew[$leafId]??0)+1;
        $studyLinks[]=['id'=>'ree-link-b638-'.$id,'material_id'=>$materialId,'question_id'=>$id,'source_ids'=>$sourceIds,'batch638'=>['wave'=>$wave,'leaf_id'=>$leafId,'scope_source_ids'=>$scopeIds]];
        $reuse[]=['id'=>'question-reuse-b638-'.$id,'question_id'=>(string)$id,'reuse'=>['reuse_policy'=>'REVIEW','required_depth'=>(int)substr($item['depth'],1),'context_mode'=>'PROFESSIONAL','metadata_status'=>'VERIFIED','metadata_provenance'=>[['type'=>'OTHER','reference'=>'batch638-source-first','note'=>'New REE canonical item; cross-board reuse remains review-only.','verified_status'=>'VERIFIED']]]];
