        $leaf=(string)($q['taxonomy']['subcompetency_id']??'');$study=(string)($q['study_material_id']??'');$link=$linkBy[$id]??[];$scope=$q['scope_source_ids']??[];$sourceList=$q['source_ids']??[];
        if(!isset($leafInfo[$leaf])||!isset($materialBy[$study])||!isset($link['material_id'])||$link['material_id']!==$study||!$scope||!$sourceList||empty($q['batch638']['derivable'])||empty($q['taxonomy']['subcompetency_confidence']))$defects[]=['id'=>$id,'kind'=>'TRACEABILITY'];
