        if(($q['batch638']['depth']??'UNKNOWN')==='UNKNOWN'||!in_array($q['batch638']['depth']??'', ['D1','D2','D3','D4','D5'],true))$defects[]=['id'=>$id,'kind'=>'DEPTH_UNKNOWN'];
        $class=(string)($q['quantitative_semantics']??'');$classes[$class]=($classes[$class]??0)+1;$calc=in_array($class,['CALCULATION_REQUIRED','MIXED_INTERPRETIVE'],true);$validClasses=['NON_NUMERICAL','CONCEPTUAL_QUANTITATIVE','CALCULATION_REQUIRED','MIXED_INTERPRETIVE'];
        if(!in_array($class,$validClasses,true)||($q['calculation_required']??false)!==$calc||((bool)($q['numeric']??false))!==($class!=='NON_NUMERICAL'))$defects[]=['id'=>$id,'kind'=>'CALCULATION_SEMANTICS'];
