        $subject=(string)($q['taxonomy']['subject_id']??'');$area=match($subject){'registered-electrical-engineering-mathematics'=>'MATHEMATICS','registered-electrical-engineering-engineering-sciences-and-allied-subjects'=>'ALLIED',default=>'PROFESSIONAL'};$areas[$area]++;$leafNew[$leaf]=($leafNew[$leaf]??0)+1;
