    $artifact['waves'][$key]=$state;$artifact['validation'][$key.'_gate']=$gate;$artifact['recovery_checkpoint']=strtoupper($key).'_GATE_COMPLETE';$artifact['status']=$gate==='PASS'?'IN_PROGRESS':'INVALID';$artifact['audit_hash']=b638_hash($artifact);
    b638_write($root.'/storage/batch638-ree-large-expansion.json',[$artifact]);
    return ['wave'=>$wave,'gate'=>$gate,'ids'=>$state['id_range'],'actual'=>count($ids),'defects'=>$defects,'after'=>$health,'area_counts'=>$areas,'audit_hash'=>$artifact['audit_hash']];
