    foreach($new as $i){$q=$questions[$i];$id=(int)$q['id'];$stem=b638_normalized_stem((string)$q['question']);if(isset($normalized[$stem]))$defects[]=['id'=>$id,'kind'=>'NORMALIZED_DUPLICATE'];else $normalized[$stem]=true;
