        foreach($q['source_ids']??[] as $source)if(!isset($sourceIndex[$source]))$defects[]=['id'=>$id,'kind'=>'BROKEN_SOURCE','source'=>$source];
        if(($q['calculation_required']??false)&&!($q['numeric']??false))$defects[]=['id'=>$id,'kind'=>'CALCULATION_SUBSET'];
        if(($q['batch638']['depth']??'UNKNOWN')==='UNKNOWN')$defects[]=['id'=>$id,'kind'=>'DEPTH_UNKNOWN'];
        if(($q['calculation_required']??false)||($q['quantitative_semantics']??'')==='MIXED_INTERPRETIVE'){$calc++;$formula=(string)($q['batch638']['calculation']['formula_and_result']??'');if(($q['batch638']['calculation']['status']??'')!=='PASS'||!str_contains($formula,'='))$defects[]=['id'=>$id,'kind'=>'CALCULATION_REVIEW'];}
