function b638_sign_misconception_family(string $leaf): string
{
    if($leaf==='b633-ree-pro-telecommunications')return 'SIGNAL_PHASE_OR_MODULATION_CONVENTION';
    if(in_array($leaf,['b633-ree-math-complex-phasors','b633-ree-math-trigonometry-analytic-geometry','b633-ree-math-fourier-laplace'],true))return 'MATH_PHASE_OR_TRANSFORM_SIGN';
    return 'POLARITY_DIRECTION_OR_SIGN_CONVENTION';
}

function b638_misconception_family(string $leaf,string $misconception): string
{
    $s=mb_strtolower($misconception,'UTF-8');
    $profile=b638_leaf_misconception_profile($leaf);
    if ($profile!==null && $misconception===$profile) return $profile;
    if ($misconception==='SIGN_PHASE_OR_DIRECTION') {
        return b638_sign_misconception_family($leaf);
    }
    if (in_array($misconception,['FORMULA_OR_MODEL_ASSUMPTION','COMPETENCY_SPECIFIC_REASONING','RATIO_OR_BASE_SELECTION','ENERGY_OR_SYSTEM_BALANCE'],true) && $profile!==null) return $profile;
    if ($profile!==null && preg_match('/assum|confus|treat|compar|attribut|equat|ignor|revers|omitt|only|solely|fail to|mistak|incorrectly|wrongly|proportion|uses?/u',$s)) return $profile;
    if(preg_match('/unit|convert|scale|millisecond|millivolt|kilowatt|kilovolt|mpa|mm²|kwh|khz|db|radian|milli|microamp|megavolt/u',$s))return 'UNIT_SCALE_CONVERSION';
    if(preg_match('/sign|negative|positive|polarity|quadrant|leading|lagging|clockwise|counterclockwise|phase angle|direction/u',$s))return b638_sign_misconception_family($leaf);
    if(preg_match('/index|endpoint|step count|term count|n−1|n-1|off.by.one|cycle count|period/u',$s))return 'INDEX_OR_BOUNDARY_COUNT';
    if(preg_match('/median|mean|correlation|probab|standard deviation|standard error|conditional|sample|confidence|statistics|average/u',$s))return 'STATISTICAL_OR_PROBABILITY_INTERPRETATION';
    if(preg_match('/calibrat|measurement|meter|instrument|sensor|reference value|accuracy|uncertainty|reading/u',$s))return 'MEASUREMENT_CHAIN_OR_UNCERTAINTY';
    if(preg_match('/hazard|safe|safety|shock|live|ground|isolation|lockout|ppe|worker|energiz|injury/u',$s))return 'ELECTRICAL_HAZARD_CONTROL';
    if(preg_match('/code|regulat|legal|draft|effective|authority|professional rule|licens|ethic|conflict/u',$s))return 'AUTHORITY_OR_PROFESSIONAL_DUTY';
    if(preg_match('/relay|breaker|fault|trip|coordination|selectiv|ct ratio|interrupt/u',$s))return 'PROTECTION_OR_SELECTIVITY';
    if(preg_match('/controller|feedback|stability|pole|damping|gain|integrator|governor|tune/u',$s))return 'CONTROL_OR_DYNAMIC_RESPONSE';
    if(preg_match('/bandwidth|alias|sampling|harmonic|spectrum|symbol|baud|snr|noise|signal|phasor/u',$s))return 'SIGNAL_OR_PHASE_MODEL';
    if(preg_match('/software|solver|model|input|provenance|version|algorithm|data pipeline|outlier|simulation/u',$s))return 'MODEL_INPUT_OR_COMPUTATION';
    if(preg_match('/ratio|reciprocal|divide|multipli|inverse|denominator|factor|percent|base conversion/u',$s))return $profile??'RATIO_OR_BASE_SELECTION';
    if(preg_match('/energy|power|loss|efficien|work|heat|thermal|flow|pressure|head|current|voltage drop/u',$s))return $profile??'ENERGY_OR_SYSTEM_BALANCE';
    if(preg_match('/matrix|equation|rank|determinant|solution|linear system|pivot/u',$s))return 'LINEAR_SYSTEM_OR_MATRIX_STRUCTURE';
    if(preg_match('/discount|cash flow|cost|salvage|present worth|economic|investment|depreciat/u',$s))return 'ENGINEERING_ECONOMIC_BASIS';
    if(preg_match('/material|fatigue|fracture|stress|strain|yield|brittle|toughness/u',$s))return 'MATERIAL_PROPERTY_OR_FAILURE_MODE';
    if(preg_match('/fluid|continuity|pipe|pump|manometer|hydraulic|density|specific gravity/u',$s))return 'FLUID_MODEL_OR_FLOW_BALANCE';
    if(preg_match('/force|moment|momentum|inertia|velocity|acceleration|work|motion/u',$s))return 'FORCE_MOTION_OR_EQUILIBRIUM';
    if(preg_match('/diode|transistor|mosfet|bjt|junction|bias|cutoff|saturation|semiconductor/u',$s))return 'DEVICE_REGION_OR_BIAS';
    if(preg_match('/contract|submittal|specification|bid|procurement|deviation|acceptance/u',$s))return 'CONTRACT_OR_DOCUMENT_CONTROL';
    if(preg_match('/formula|equation|uses |assumes|ignores|confuses|reverses|omits|treats/u',$s))return $profile??'FORMULA_OR_MODEL_ASSUMPTION';
    return $profile??'COMPETENCY_SPECIFIC_REASONING';
}

