    $artifact['diversity_normalization']=['new_questions_updated'=>$updated,'scenario_families'=>$scenario,'misconception_families'=>$misconception,'scenario_count'=>count($scenario),'misconception_count'=>count($misconception),'method'=>'Competency-level scenario structures with cross-leaf semantic misconception classes; no wording-derived one-item labels retained.'];$artifact['audit_hash']=b638_hash($artifact);b638_write($root.'/storage/questions.json',$questions);b638_write($root.'/storage/batch638-ree-large-expansion.json',[$artifact]);
    return ['updated'=>$updated,'scenario_families'=>count($scenario),'misconception_families'=>count($misconception),'max_scenario_family'=>$scenario?max($scenario):0,'max_misconception_family'=>$misconception?max($misconception):0];
}

